// RAW Hazard (Read After Write - True Dependency)
// Inst 2 needs R1, which Inst 1 has not yet written back.
ADD R1, R2, R3      // Inst 1: Write R1
SUB R4, R1, R5      // Inst 2: Read R1 (Stall required here)

// Pipeline Stages (Simple 5-Stage MIPS):
// T3: ADD in EX stage (R1 calculated)
// T4: SUB in ID/EX (Needs R1, registers stale)

// --------------------------------------------------

// WAW Hazard (Write After Write - Output Dependency)
// Both instructions write to R6. Inst 2 must be the final result.
MUL R6, R7, R8      // Inst 1: Write R6
ADDI R6, R9, #1     // Inst 2: Write R6

// Hazard occurs if Inst 1's Write Back (WB) stage finishes
// AFTER Inst 2's WB stage, corrupting the final result.

// --------------------------------------------------

// Data Hazard Mitigation: Forwarding (Bypassing)
// Result from EX/MEM latch is fed back to the ALU input.
ADD R1, R2, R3      // R1 available after EX stage
SUB R4, R1, R5      // R1 forwarded from ADD's EX output

// (Stall avoided: SUB receives R1 value directly
// from ADD's execution unit, skipping the Register File wait.)
